create type public.reminder_offset_type as enum ('before_due','on_due','after_due');
create type public.reminder_job_status as enum ('pending','processing','sent','failed','cancelled');
create table if not exists public.reminder_rules (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, name text not null, offset_days integer not null, offset_type public.reminder_offset_type not null, template_id text, active boolean not null default true, created_at timestamptz not null default timezone('utc',now()), updated_at timestamptz not null default timezone('utc',now()), constraint reminder_rules_name_nonempty check(length(trim(name))>0), constraint reminder_rules_offset_nonnegative check(offset_days>=0));
create table if not exists public.reminder_jobs (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, invoice_id uuid not null references public.invoices(id) on delete cascade, reminder_rule_id uuid not null references public.reminder_rules(id) on delete cascade, scheduled_for timestamptz not null, status public.reminder_job_status not null default 'pending', attempt_count integer not null default 0, sent_at timestamptz, last_error text, created_at timestamptz not null default timezone('utc',now()), updated_at timestamptz not null default timezone('utc',now()), constraint reminder_jobs_attempt_nonnegative check(attempt_count>=0));
create index if not exists reminder_rules_business_id_idx on public.reminder_rules(business_id);
create index if not exists reminder_jobs_business_id_idx on public.reminder_jobs(business_id);
create index if not exists reminder_jobs_invoice_id_idx on public.reminder_jobs(invoice_id);
create index if not exists reminder_jobs_status_scheduled_for_idx on public.reminder_jobs(status,scheduled_for);
create unique index if not exists reminder_jobs_idempotency_idx on public.reminder_jobs(invoice_id,reminder_rule_id,scheduled_for);
create or replace function public.validate_reminder_job_business() returns trigger language plpgsql security invoker set search_path=public as $$ declare ib uuid; rb uuid; begin select business_id into ib from public.invoices where id=new.invoice_id; select business_id into rb from public.reminder_rules where id=new.reminder_rule_id; if ib is null or ib<>new.business_id then raise exception 'Reminder job invoice does not belong to job business'; end if; if rb is null or rb<>new.business_id then raise exception 'Reminder job rule does not belong to job business'; end if; return new; end; $$;
drop trigger if exists validate_reminder_job_business on public.reminder_jobs;
create trigger validate_reminder_job_business before insert or update on public.reminder_jobs for each row execute function public.validate_reminder_job_business();
alter table public.reminder_rules enable row level security;
alter table public.reminder_jobs enable row level security;
drop policy if exists "business members can read reminder rules" on public.reminder_rules;
create policy "business members can read reminder rules" on public.reminder_rules for select using (exists(select 1 from public.business_members bm where bm.business_id=reminder_rules.business_id and bm.user_id=auth.uid()));
drop policy if exists "business members can manage reminder rules" on public.reminder_rules;
create policy "business members can manage reminder rules" on public.reminder_rules for all using (exists(select 1 from public.business_members bm where bm.business_id=reminder_rules.business_id and bm.user_id=auth.uid())) with check (exists(select 1 from public.business_members bm where bm.business_id=reminder_rules.business_id and bm.user_id=auth.uid()));
drop policy if exists "business members can read reminder jobs" on public.reminder_jobs;
create policy "business members can read reminder jobs" on public.reminder_jobs for select using (exists(select 1 from public.business_members bm where bm.business_id=reminder_jobs.business_id and bm.user_id=auth.uid()));
